            try:
                return _fast_dot(A, B)
            except ValueError:
                return np.dot(A, B)
        except (AttributeError, ValueError):
            warnings.warn('Could not import BLAS, falling back to np.dot')
            return np.dot(A, B)
    else:
        return np.dot(A, B)

